1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE = 25;
4	const COMPONENT_BLOCK_BASE = 60;
5	const COMPONENT_BLOCK_SIZE = 3;
6	
7	const BASE_PREMIUM: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	
14	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
15	
16	type Item = { type: string };
17	type Step = { op: "quote"; items: Item[] };
18	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
19	
20	const basePremiumForComponentCount = (count: number): number =>
21	  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE : count * COMPONENT_BASE;
22	
23	const countByType = (items: Item[]): Map<string, number> =>
24	  items.reduce(
25	    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
26	    new Map<string, number>(),
27	  );
28	
29	const basePremiumForItemGroup = (type: string, count: number): number =>
30	  COMPONENT_TYPES.has(type) ? basePremiumForComponentCount(count) : count * BASE_PREMIUM[type];
31	
32	const basePremiumFor = (items: Item[]): number =>
33	  [...countByType(items)].reduce(
34	    (sum, [type, count]) => sum + basePremiumForItemGroup(type, count),
35	    0,
36	  );
37	
38	const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);
39	
40	const withFirstInsuranceSurcharge = (base: number): number =>
41	  base + base * FIRST_INSURANCE_SURCHARGE_RATE;
42	
43	const quotePremium = (step: Step): number =>
44	  roundInMHPCOsFavor(withFirstInsuranceSurcharge(basePremiumFor(step.items))) + PROCESSING_FEE;
45	
46	export const runScenario = (scenario: Scenario): { results: Array<{ premium: number }> } => ({
47	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
48	});
